<?php use VazinCMS\Security; ?><section class="title"><div><h1>سفارش‌ها</h1><p>ثبت و پیگیری سفارش مشتریان</p></div></section><?php if($error):?><div class="alert"><?=Security::e($error)?></div><?php endif;?><section class="split"><div class="panel"><h2>سفارش جدید</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>مشتری<select name="user_id" required><option value="">انتخاب</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=Security::e($c['name'].' — '.$c['email'])?></option><?php endforeach;?></select></label><label>محصول<select name="product_id" required><option value="">انتخاب</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=Security::e($p['name'].' — '.$p['price_amount'].' '.$p['currency'])?></option><?php endforeach;?></select></label><label>کد تخفیف<input name="discount_code" maxlength="40" placeholder="اختیاری"></label><label>یادداشت<textarea name="notes" rows="4"></textarea></label><button>ثبت سفارش</button></form></div><div class="panel"><form class="filters compact" method="get"><label>وضعیت<select name="status"><option value="">همه</option><?php foreach(['pending'=>'در انتظار','paid'=>'پرداخت‌شده','processing'=>'در حال انجام','completed'=>'تکمیل','cancelled'=>'لغو','refunded'=>'بازپرداخت'] as $v=>$l):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><button>فیلتر</button></form><div class="table"><table><thead><tr><th>شماره</th><th>مشتری</th><th>محصول</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="/admin/orders/<?=$o['id']?>"><?=Security::e($o['order_number'])?></a></td><td><?=Security::e($o['customer'])?></td><td><?=Security::e($o['product_name'])?></td><td><?=Security::e((string)$o['amount'].' '.$o['currency'])?></td><td><span class="status <?=Security::e($o['status'])?>"><?=Security::e($o['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div></section>
